CREATE TEMPORARY VIEW dump_status_${grass_region_without_quote} AS
select -- dump的时候，有重复，要先去重（flink dump 的时候如果 instance 重试了，可能会写进去多条，按 cspu x item 随便取一条可以么？）
     item_id
    ,cspu_id
    ,pruning_tag
    ,exp_tag
from(
    SELECT
         item_id
        ,cspu_id
        ,pruning_tag
        ,case
           when pruning_tag in ('can_not_explore','obvious_bad') then 'non_preferred'
           when pruning_tag in ('obvious_good') then 'preferred' -- 一定要分开，先把purning tag的判断用完，在用explore_status，因为pruning_tag更准
           when explore_status='prefered'       then 'preferred'
           when explore_status='non_prefer'     then 'non_preferred'
           when explore_status in ('explore','invalid','prepare') then 'explore'
         end as exploration_status
        ,exp_tag
        ,row_number() over (partition by exp_tag,item_id,cspu_id order by version_date desc) as rn
    FROM rcmd_feature.cheapest_v3_daily_status_info_df
    where grass_region in (${grass_region}) and grass_date = ${local_date}
) a
where a.rn=1 and pruning_tag is not null
and exploration_status in ('non_preferred','preferred') --对于状态恒定的，予以回捞
and exp_tag in ('T2') --限定使用监控回退的策略
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW pruning_exp_${grass_region_without_quote} AS
SELECT
     exp_tag
    ,item_id
    ,pruning_tag
FROM srdi_mart.dim_sr_data_warehouse_pb_rcmd_replace_pruning_tag_df
where grass_region in (${grass_region})
and local_date = data_infra.max_pt('srdi_mart.dim_sr_data_warehouse_pb_rcmd_replace_pruning_tag_df', 'local_date', "grass_region=${grass_region} and local_date<=${local_date}")
and exp_tag in ('T2') --限定使用监控回退的策略
;
--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dwd_sr_data_warehouse_pb_rcmd_replace_monitoring_v3_nd partition(grass_region = ${grass_region}, local_date=${local_date})
select
     a.exp_tag
    ,a.cspu_id
    ,a.item_id
    ,cast(replace(date_add(${local_date},1), '-', '') as int) as version_date --用任务运行日作为版本号
from dump_status_${grass_region_without_quote} a
inner join pruning_exp_${grass_region_without_quote} b on a.item_id=b.item_id and a.exp_tag=b.exp_tag
where a.pruning_tag!=b.pruning_tag
;
